const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon([[
    [-71.0, -30.0],
    [-68.0, -30.0],
    [-68.0, -33.0],
    [-71.0, -33.0],
    [-71.0, -30.0]
  ]]);

  const date1 = '2022-07-07';
  const date2 = '2022-07-16';

  // 2. Data Acquisition - MODIS Snow Cover
  const modis = ee.ImageCollection('MODIS/061/MOD10A1')
    .filterBounds(geometry);

  const img1 = modis.filterDate(date1, ee.Date(date1).advance(1, 'day')).first();
  const img2 = modis.filterDate(date2, ee.Date(date2).advance(1, 'day')).first();

  // Check for empty collections
  const img1Exists = img1 && ee.Algorithms.IsEqual(img1, null).not().getInfo();
  const img2Exists = img2 && ee.Algorithms.IsEqual(img2, null).not().getInfo();

  if (!img1Exists || !img2Exists) {
    console.log(`July 7 image exists: ${img1Exists}, July 16 image exists: ${img2Exists}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Process snow data - NDSI_Snow_Cover band (0-100 snow cover percentage)
  // Mask invalid values (>100)
  const snow1 = img1.select('NDSI_Snow_Cover').updateMask(img1.select('NDSI_Snow_Cover').lte(100));
  const snow2 = img2.select('NDSI_Snow_Cover').updateMask(img2.select('NDSI_Snow_Cover').lte(100));

  // Calculate snow area (sum of snow cover percentages)
  const snowArea1 = snow1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover');

  const snowArea2 = snow2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover');

  // Get pixel counts to check for valid data
  const count1 = snow1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover');

  const count2 = snow2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover');

  const area1Val = snowArea1.getInfo();
  const area2Val = snowArea2.getInfo();
  const count1Val = count1.getInfo();
  const count2Val = count2.getInfo();

  console.log(`July 7: Area=${area1Val?.toFixed(0)}, Pixels=${count1Val}`);
  console.log(`July 16: Area=${area2Val?.toFixed(0)}, Pixels=${count2Val}`);

  // Check for no valid pixels
  if (count1Val === 0 || count2Val === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (area1Val === null || area2Val === null || 
      isNaN(area1Val) || isNaN(area2Val) ||
      area1Val < 0 || area2Val < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare snow areas
  if (area2Val > area1Val) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
